  const session=await hash(this.a.token||''),w=await this.a.one('SELECT * FROM ops_workers WHERE id=?',workerId);if(w&&(w.runtime_id!==runtime.runtimeId||w.actor!==actor||w.session_hash!==session))this.fail(409,'执行者已绑定其他运行身份或会话。');
  const t=this.clock(),id=uuid(),token=uuid(),schedules=await this.a.all('SELECT * FROM ops_task_schedules WHERE next_due<=? AND lease_until<=? ORDER BY next_due,kind',t,t),candidate=schedules.find((s:any)=>cfg.tasks[s.kind]?.enabled),kind=candidate?.kind||'idle',enabled="EXISTS(SELECT 1 FROM ops_task_config WHERE id=1 AND json_extract(data,'$.revision')=? AND json_type(data,'$.enabled')='true' AND json_type(data,'$.confirmed')='true')";
  const ops=[this.a.stmt('INSERT OR IGNORE INTO ops_workers VALUES(?,?,?,?,?,\'active\',\'\',?,?)',workerId,runtime.runtimeId,actor,session,t,t,t),this.a.stmt("UPDATE ops_workers SET last_heartbeat=?,status='active',last_error='',updated=? WHERE id=? AND runtime_id=? AND actor=? AND session_hash=?",t,t,workerId,runtime.runtimeId,actor,session)];
  if(candidate){
   ops.push(this.a.stmt(`UPDATE ops_task_runs SET status='unknown',last_error='lease_lost',finished=? WHERE kind=? AND status='running' AND lease_until<=? AND ${enabled}`,t,kind,t,cfg.revision));
   ops.push(this.a.stmt(`UPDATE ops_task_schedules SET lease_token=?,lease_until=?,config_revision=?,last_run_id=?,next_due=? WHERE kind=? AND next_due<=? AND lease_until<=? AND ${enabled} AND NOT EXISTS(SELECT 1 FROM ops_task_runs WHERE actor=? AND request_id=?)`,token,t+60000,cfg.revision,id,t+cfg.tasks[kind].intervalSeconds*1000,kind,t,t,cfg.revision,actor,requestId));
  }
