  await this.a.db.batch(ops);let row=await this.a.one('SELECT * FROM ops_task_runs WHERE actor=? AND request_id=?',actor,requestId);if(!row)this.fail(409,'任务配置或领取状态已变化。');if(row.fingerprint!==fp)this.fail(409,'请求号已用于其他任务。');if(row.id!==id)return this.result(row,true);if(!candidate)return this.result(row);
